arguments.file_text:
@implements IDisposable

<div class="checkout-wizard">
    @switch (_step)
    {
        case WizardStep.Shipping:
            <ShippingStep Shipping="_order.Shipping" OnNext="HandleShippingComplete" />
            break;

        case WizardStep.Payment:
            <PaymentStep Payment="_order.Payment"
                         OnBack="HandleBackToShipping"
                         OnPlaceOrder="HandlePlaceOrder" />
            break;
    }
</div>

@code {
    [Parameter]
    public EventCallback<Order> OnOrderPlaced { get; set; }

    private enum WizardStep { Shipping, Payment }

    private WizardStep _step = WizardStep.Shipping;
    private readonly Order _order = new();

    // Hold a reference so we can dispose the ShippingStep's validator on teardown.
    private CancellationTokenSource? _wizardCts = new();

    private void HandleShippingComplete()
    {
        _step = WizardStep.Payment;
    }

    private void HandleBackToShipping()
    {
        _step = WizardStep.Shipping;
    }

    private async Task HandlePlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }

    public void Dispose()
    {
        _wizardCts?.Cancel();
        _wizardCts?.Dispose();
        _wizardCts = null;
    }
}

@implements IDisposable
@inject IAddressValidator AddressValidator

<fieldset disabled="@_isValidating">
    <legend>Shipping Information</legend>

    <label>
        Name
        <input @bind="Shipping.Name" @bind:event="oninput" />
    </label>

    <label>
        Address
        <input @bind="Shipping.Address" @bind:event="oninput" />
    </label>

    <label>
        City
        <input @bind="Shipping.City" @bind:event="oninput" />
    </label>

    <label>
        Zip Code
        <input @bind="Shipping.ZipCode" @bind:event="oninput" />
    </label>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="validation-error" role="alert">@_errorMessage</div>
    }
</fieldset>

<button disabled="@_isValidating" @onclick="ValidateAndProceed">
    @if (_isValidating)
    {
        <span class="spinner" aria-hidden="true"></span>
        @:Validating…
    }
    else
    {
        @:Next
    }
</button>

@code {
    [Parameter, EditorRequired]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private bool _isValidating;
    private string? _errorMessage;

    // Recreated on every validation attempt so a stale call is automatically cancelled.
    private CancellationTokenSource? _validationCts;

    private async Task ValidateAndProceed()
    {
        // Cancel any in-flight validation (e.g. user went back and clicked Next again).
        CancelPendingValidation();

        _errorMessage = null;
        _isValidating = true;

        var cts = new CancellationTokenSource();
        _validationCts = cts;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, cts.Token);

            // If this CTS was replaced while we were awaiting, another call owns the UI now.
            if (cts.Token.IsCancellationRequested)
                return;

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _errorMessage = "The address could not be verified. Please check and try again.";
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when the user navigates away or retries — nothing to do.
        }
        catch (Exception)
        {
            if (!cts.Token.IsCancellationRequested)
            {
                _errorMessage = "Address validation failed. Please try again.";
            }
        }
        finally
        {
            // Only touch UI state if *this* call is still the active one.
            if (_validationCts == cts)
            {
                _isValidating = false;
            }

            cts.Dispose();
        }
    }

    private void CancelPendingValidation()
    {
        _validationCts?.Cancel();
        _validationCts?.Dispose();
        _validationCts = null;
    }

    public void Dispose()
    {
        CancelPendingValidation();
    }
}

